import{_ as i,C as a,o as n,c as l,j as d,a as e,E as o,a5 as c}from"./chunks/framework.CINlqUGR.js";const P=JSON.parse('{"title":"步骤条","description":"","frontmatter":{},"headers":[],"relativePath":"components/steps.md","filePath":"components/steps.md","lastUpdated":1787598366000}'),p={name:"components/steps.md"},h={id:"步骤条",tabindex:"-1"};function u(b,t,g,m,x,f){const s=a("Badge"),r=a("XhDemo");return n(),l("div",null,[d("h1",h,[t[0]||(t[0]=e("步骤条 ",-1)),o(s,{type:"info",text:"steps"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#步骤条","aria-label":'Permalink to "步骤条 <Badge type="info" text="steps" />"'},"​",-1))]),t[3]||(t[3]=c('<p>把一件事拆成有先后的几步，并标出走到哪一步了。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>多步表单、开通流程、安装向导，步数固定且顺序明确。</li><li>需要让用户看见&quot;还剩几步&quot;。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>各段之间没有先后、可以随便切：那是<a href="./tabs">标签页</a>。</li><li>展示已经发生的事件序列：用<a href="./timeline">时间线</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>count</code> 是步序的上界，也是读屏&quot;第 k 步，共 n 步&quot;的分母。</li><li><code>linear</code> 只拦界面上的乱跳（未解锁的入口一律禁用），逐步前进的方法照常可用。</li><li>方向键只搬焦点，按 Enter 或空格才切步。</li><li>&quot;这一步出错了&quot;是宿主自己的数据：在那一步上换掉标记与颜色令牌即可。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>不传 step 即为非受控；方向键只搬焦点，按 Enter 或空格才切步，进退方法由 root 的插槽交出来</p>',10)),o(r,{src:"steps/01-basic"}),t[4]||(t[4]=d("h3",{id:"受控",tabindex:"-1"},[e("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),t[5]||(t[5]=d("p",null,"传了 step 就由宿主说了算，组件自己不再改步序；切步意图从 step-change 出来，写回才真的切",-1)),o(r,{src:"steps/02-controlled"}),t[6]||(t[6]=d("h3",{id:"线性模式",tabindex:"-1"},[e("线性模式 "),d("a",{class:"header-anchor",href:"#线性模式","aria-label":'Permalink to "线性模式"'},"​")],-1)),t[7]||(t[7]=d("p",null,"linear 下还没走到的步一律禁用，只能回头看走过的；它只拦界面上的乱跳，逐步前进照常",-1)),o(r,{src:"steps/03-linear"}),t[8]||(t[8]=d("h3",{id:"竖排",tabindex:"-1"},[e("竖排 "),d("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),t[9]||(t[9]=d("p",null,'orientation="vertical" 把步骤列与面板并排摆，方向键随之改收上下键',-1)),o(r,{src:"steps/04-vertical"}),t[10]||(t[10]=d("h3",{id:"语气",tabindex:"-1"},[e("语气 "),d("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=d("p",null,"tone 决定已完成与当前这两步的标记、连接线用哪族颜色；示例预置到第 2 步，第 1 步已走完",-1)),o(r,{src:"steps/05-tone"}),t[12]||(t[12]=d("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=d("p",null,"size 换序号圆点的直径与标题、说明的字号，不传 size 即默认档",-1)),o(r,{src:"steps/06-size"}),t[14]||(t[14]=d("h3",{id:"点击切步与禁用某步",tabindex:"-1"},[e("点击切步与禁用某步 "),d("a",{class:"header-anchor",href:"#点击切步与禁用某步","aria-label":'Permalink to "点击切步与禁用某步"'},"​")],-1)),t[15]||(t[15]=d("p",null,"点标签直接切到那一步；单步标了 disabled 就点不动，方向键也跳过它",-1)),o(r,{src:"steps/07-click"}),t[16]||(t[16]=d("h3",{id:"出错的那一步",tabindex:"-1"},[e("出错的那一步 "),d("a",{class:"header-anchor",href:"#出错的那一步","aria-label":'Permalink to "出错的那一步"'},"​")],-1)),t[17]||(t[17]=d("p",null,"步序只认下标，「这一步出错了」是宿主自己的数据：在那一步的 item 上换掉标记与颜色令牌",-1)),o(r,{src:"steps/08-error-step"}),t[18]||(t[18]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-steps&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhStepsContent</code> <code>XhStepsDescription</code> <code>XhStepsIndicator</code> <code>XhStepsItem</code> <code>XhStepsList</code> <code>XhStepsRoot</code> <code>XhStepsSeparator</code> <code>XhStepsTitle</code> <code>XhStepsTrigger</code></td></tr><tr><td>组合式函数</td><td><code>useSteps</code></td></tr><tr><td>状态机</td><td><code>stepsMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/steps.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;steps&quot;</code>：<strong><code>root</code></strong> · <strong><code>list</code></strong> · <strong><code>item</code></strong> · <strong><code>trigger</code></strong> · <code>indicator</code> · <code>title</code> · <code>description</code> · <code>separator</code> · <code>content</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>step</code></td><td><code>number</code></td><td></td><td>当前步序（0 起）。给定即受控：内部不再自改，只发 onStepChange。</td></tr><tr><td><code>defaultStep</code></td><td><code>number</code></td><td></td><td>非受控初值，默认 0。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>总步数，是步序的上界与读屏&quot;第 k 步，共 n 步&quot;的分母。 缺省按 0 处理：此时 root 带 data-empty，步序被夹死在 0。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 horizontal；不同轴的方向键放行给页面滚动与读屏。</td></tr><tr><td><code>linear</code></td><td><code>boolean</code></td><td></td><td>线性模式：只能回头看走过的步。未解锁（index &gt; step）的 trigger 一律禁用。 只拦跳转，goToNextStep 逐步前进照常可用。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整组不可交互：trigger 全部退出 Tab 序列，指针与键盘都不认。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只影响水平轴上 ArrowLeft/ArrowRight 的前后语义。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>onStepChange</code></td><td><code>(details: StepsStepChangeDetails) =&gt; void</code></td><td></td><td>步序变化意图回调；受控时是唯一出口，非受控随内部写入一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>step-change</code></td><td><code>StepsStepChangeDetails</code></td><td>步序变化；detail 为 <code>{ step: number }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhStepsRoot</code></td><td><code>default</code></td><td><code>StepsRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>s.status</td></tr><tr><td><code>trigger</code></td><td>s.status</td></tr><tr><td><code>indicator</code></td><td>getItemState(item).status</td></tr><tr><td><code>title</code></td><td>getItemState(item).status</td></tr><tr><td><code>description</code></td><td>getItemState(item).status</td></tr><tr><td><code>separator</code></td><td>getItemState(item).status</td></tr><tr><td><code>content</code></td><td>getItemState(item).status</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>STEP.SET</code> · <code>STEP.PREV</code> · <code>STEP.NEXT</code> · <code>TRIGGER.FOCUS</code> · <code>LIST.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useSteps</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>step</code></td><td><code>number</code></td><td>当前步序，恒在 [0, count] 内：count 变小后停在越界步也读得到一个可用的值。</td></tr><tr><td><code>count</code></td><td><code>number</code></td><td></td></tr><tr><td><code>complete</code></td><td><code>boolean</code></td><td>全部走完（step 走到 count）。此时没有任何一步是 current，作者据此渲染完成页。</td></tr><tr><td><code>focusedStep</code></td><td><code>number | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>getItemState</code></td><td><code>(props: StepsItemProps) =&gt; StepsItemState</code></td><td></td></tr><tr><td><code>setStep</code></td><td><code>(next: number) =&gt; void</code></td><td>直接跳到某一步；越界会被夹回 [0, count]。 不认 linear：linear 只拦界面上的乱跳，不拦作者的命令式调用。</td></tr><tr><td><code>goToNextStep</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>goToPrevStep</code></td><td><code>() =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getListProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTriggerProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;button&#39;]</code></td><td></td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>(props: StepsItemProps) =&gt; T[&#39;element&#39;]</code></td><td>面板按 index 与当前步配对；未命中的常挂并带 hidden。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/tabs/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>focus in list, 按键与 orientation 同轴</td><td>焦点移到下一个可停留 trigger（禁用与 linear 未解锁的跳过，尽头不回绕）；步序不变</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>focus in list, 按键与 orientation 同轴</td><td>焦点移到上一个可停留 trigger；步序不变</td></tr><tr><td><code>Home</code></td><td>focus in list</td><td>焦点移到首个可停留 trigger</td></tr><tr><td><code>End</code></td><td>focus in list</td><td>焦点移到末个可停留 trigger</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus in trigger, 未禁用且已解锁</td><td>把当前步切到焦点所在的那一步</td></tr><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus in list</td><td>整组只有锚点 trigger 留在 Tab 序列内，一次 Tab 进出；无锚点时由 list 兜底</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>list</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>list</code></td><td><code>role</code></td><td>&#39;tablist&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-controls</code></td><td><code>content</code> 部件的 id</td></tr><tr><td><code>trigger</code></td><td><code>aria-current</code></td><td>&#39;step&#39; | undefined</td></tr><tr><td><code>trigger</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-posinset</code></td><td>item.index + 1 | undefined</td></tr><tr><td><code>trigger</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>trigger</code></td><td><code>aria-setsize</code></td><td>normalizeStepCount(prop(&#39;count&#39;)) | undefined</td></tr><tr><td><code>trigger</code></td><td><code>role</code></td><td>&#39;tab&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>trigger</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;tabpanel&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/steps.css</code> 按部件选择：<code>[data-scope=&quot;steps&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-empty</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>list</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>s.status</td></tr><tr><td><code>trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>trigger</code></td><td><code>data-state</code></td><td>s.status</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>getItemState(item).status</td></tr><tr><td><code>title</code></td><td><code>data-state</code></td><td>getItemState(item).status</td></tr><tr><td><code>description</code></td><td><code>data-state</code></td><td>getItemState(item).status</td></tr><tr><td><code>separator</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>separator</code></td><td><code>data-state</code></td><td>getItemState(item).status</td></tr><tr><td><code>content</code></td><td><code>data-state</code></td><td>getItemState(item).status</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-steps-content-fg</code> · <code>--xh-steps-content-py</code> · <code>--xh-steps-description-fg</code> · <code>--xh-steps-description-font-size</code> · <code>--xh-steps-gap</code> · <code>--xh-steps-icon-size</code> · <code>--xh-steps-indicator-bg</code> · <code>--xh-steps-indicator-bg-completed</code> · <code>--xh-steps-indicator-border</code> · <code>--xh-steps-indicator-border-completed</code> · <code>--xh-steps-indicator-border-current</code> · <code>--xh-steps-indicator-border-disabled</code> · <code>--xh-steps-indicator-fg</code> · <code>--xh-steps-indicator-fg-completed</code> · <code>--xh-steps-indicator-fg-current</code> · <code>--xh-steps-indicator-fg-disabled</code> · <code>--xh-steps-indicator-font-size</code> · <code>--xh-steps-indicator-radius</code> · <code>--xh-steps-indicator-size</code> · <code>--xh-steps-item-gap</code> · <code>--xh-steps-list-gap</code> · <code>--xh-steps-separator-bg</code> · <code>--xh-steps-separator-bg-completed</code> · <code>--xh-steps-separator-min-length</code> · <code>--xh-steps-separator-radius</code> · <code>--xh-steps-separator-thickness</code> · <code>--xh-steps-title-fg</code> · <code>--xh-steps-title-fg-active</code> · <code>--xh-steps-title-font-size</code> · <code>--xh-steps-title-font-weight</code> · <code>--xh-steps-trigger-bg-hover</code> · <code>--xh-steps-trigger-gap</code> · <code>--xh-steps-trigger-p</code> · <code>--xh-steps-trigger-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./form">表单</a>配合做分步表单；每步的内容放进 <code>content</code> 部件。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>步数控制在三到五步，多了就把相邻两步合并。</li><li>每步的标题写用户要做的事，不写&quot;第一步&quot;。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>步数会变：用户刚看到&quot;共 3 步&quot;，走到一半变成 5 步。</li><li>用它表达进度百分比：那是<a href="./progress">进度条</a>。</li></ul>',47))])}const q=i(p,[["render",u]]);export{P as __pageData,q as default};
